ssize_t receive_and_process_message(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags) {
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    ssize_t copied = 0;
    int err = 0;

    if (sk->sk_state == TCP_CLOSE)
        return -ENOTCONN;

    if (sk->sk_receive_queue == NULL) {
        if (flags & MSG_DONTWAIT)
            return -EAGAIN;
        else
            return -EWOULDBLOCK;
    }

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    if (flags & MSG_OOB)
        skb = skb_peek(&sk->sk_peek_head);

    if (sock->type == SOCK_DGRAM) {
        struct sockaddr *addr = (struct sockaddr *)&msg->msg_name;
        int addr_len = msg->msg_namelen;
        if (addr && addr_len)
            memcpy(addr, &skb->cb, addr_len);
    }

    copied = skb->len;
    if (copied > len)
        copied = len;

    if (skb_copy_datagram_const(sk, skb, 0, msg->msg_iov, copied, flags))
        err = -EFAULT;

    if (!err && (flags & MSG_PEEK)) {
        skb_queue_head(&sk->sk_receive_queue, skb);
        copied = 0;
    } else {
        kfree_skb(skb);
    }

    if (err)
        return err;

    return copied;
}

ssize_t receive_and_process_message(struct kiocb *iocb, struct socket *sock,
                                    struct msghdr *msg, size_t len, int flags)
{
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    ssize_t copied = 0;
    int err;

    if (sk->sk_state == TCP_LISTEN) {
        return -EINVAL;
    }

    if (skb_queue_empty(&sk->sk_receive_queue)) {
        if (flags & MSG_DONTWAIT) {
            return -EAGAIN;
        }
        wait_for_receive_data(sk);
    }

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb) {
        return -EAGAIN;
    }

    if (flags & MSG_OOB) {
        handle_out_of_band_data(sk, skb);
    }

    if (sock->type == SOCK_DGRAM) {
        if (msg->msg_name)
            memcpy((void *)msg->msg_name, skb->cb, sock->family->sysctl_addr_len);
        msg->msg_namelen = sock->family->sysctl_addr_len;
    }

    copied = skb->len;
    if (copied > len)
        copied = len;

    if (copy_to_iter(skb->data, copied, msg->msg_iter) != copied) {
        skb_queue_head(&sk->sk_receive_queue, skb);
        return -EFAULT;
    }

    if (sock->type == SOCK_STREAM) {
        if (skb_has_remaining(skb)) {
            skb_queue_head(&sk->sk_receive_queue, skb);
        } else {
            kfree_skb(skb);
        }
    }

    return copied;
}

ssize_t sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags) {
    struct sock *sk = sock->sk;
    ssize_t copied = 0;
    struct sk_buff *skb;

    if (sk->sk_state == TCP_LISTEN)
        return -EINVAL;

    if (sk->sk_type == SOCK_DGRAM) {
        skb = skb_recv_datagram(sk, flags, &copied);
        if (!skb)
            return (copied == 0) ? -EAGAIN : copied;

        if (msg->msg_name && skb->skb_iif)
            msg->msg_namelen = sizeof(struct sockaddr_in);
        msg->msg_flags = skb->destructor_flags;

        if (skb->data != NULL) {
            size_t skb_len = skb->len;
            if (len > skb_len)
                len = skb_len;
            copied = len;
            if (memcpy_to_msg(msg, skb->data, len) != 0)
                return -EFAULT;
        }
        kfree_skb(skb);
        return copied;
    }

    return -EOPNOTSUPP;
}

ssize_t receive_and_process_message(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags) {
    struct sock *sk = sock->sk;
    ssize_t copied = 0;
    struct sk_buff *skb;

    if (sk->sk_state == TCP_LISTEN)
        return -EINVAL;

    if (flags & MSG_OOB) {
        return -EOPNOTSUPP;
    }

    if (sk->sk_type == SOCK_DGRAM) {
        skb = skb_dequeue(&sk->sk_receive_queue);
        if (!skb)
            return -EAGAIN;

        if (msg->msg_name) {
            struct sockaddr *addr = (struct sockaddr *)msg->msg_name;
            sock->ops->getname(sock, addr, 0);
            msg->msg_namelen = sizeof(*addr);
        }

        copied = skb->len;
        if (copied > len)
            copied = len;

        if (memcpy_to_msg(msg, skb->data, copied))
            return -EFAULT;

        if (skb->len > copied) {
            skb_trim(skb, skb->len - copied);
            skb_queue_head(&sk->sk_receive_queue, skb);
        } else {
            kfree_skb(skb);
        }
    } else {
        return -EOPNOTSUPP;
    }

    return copied;
}

int receive_and_process_message(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags) {
    struct sock *sk = sock->sk;
    int ret = 0;
    struct sk_buff *skb;
    int copied = 0;

    if (sk->sk_state == TCP_CLOSE)
        return -ENOTCONN;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb) {
        if (flags & MSG_DONTWAIT)
            return -EAGAIN;

        return -EWOULDBLOCK;
    }

    if (flags & MSG_OOB) {
        skb = skb_peek(&sk->sk_urgent_queue);
        if (!skb) {
            skb_dequeue(&sk->sk_urgent_queue);
        }
    }

    copied = skb->len;
    if (len < copied) {
        if (!(flags & MSG_TRUNC))
            copied = len;
        else
            copied = skb->len;
    }

    if (msg) {
        ret = skb_copy_datagram_to_iter(skb, 0, &msg->msg_iter, copied);
        if (ret)
            return ret;

        if (sock->type == SOCK_DGRAM && skb->cb) {
            msg->msg_name = skb->cb;
            msg->msg_namelen = sizeof(struct sockaddr_in);
        }
    }

    if (sock->type == SOCK_STREAM)
        skb_queue_head(&sk->sk_receive_queue, skb);
    else
        kfree_skb(skb);

    return copied;
}
